def is_undulating(n):
    # Convert the number to a string to easily access individual digits
    s = str(n)

    # Check if the number has less than 3 digits, it cannot be undulating
    if len(s) < 3:
        return False

    # Check if the number is undulating by comparing adjacent digits
    for i in range(2, len(s)):
        if s[i] != s[i - 2]:
            return False

    return True
